#include <stdio.h>
#include <limits.h>
int main(void){
    int n=5;
    int g[5][5]={{0}};
    g[0][1]=4; g[0][2]=1; g[2][1]=2; g[1][3]=1; g[2][3]=5; g[3][4]=3;
    int dist[5], done[5]={0};
    for(int i=0;i<n;i++) dist[i]=INT_MAX/2;
    dist[0]=0;
    for(int it=0;it<n;it++){
        int u=-1,best=INT_MAX;
        for(int i=0;i<n;i++) if(!done[i] && dist[i]<best){ best=dist[i]; u=i; }
        if(u<0) break;
        done[u]=1;
        for(int v=0;v<n;v++) if(g[u][v] && dist[u]+g[u][v]<dist[v]) dist[v]=dist[u]+g[u][v];
    }
    printf("dist from 0: ");
    for(int i=0;i<n;i++) printf("%d ", dist[i]);
    printf("\n");
    return 0;
}
